"""Isolated design preview; keeps the original homepage available."""

STUDIO_CSS = r"""/* AI Design Skills: named typography, spacing scale and decelerating motion. */
@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&display=swap');
:root,[data-theme="dark"]{--bg:#181818;--surface:#1f1f1f;--surface-2:#272727;--ink:#f5f5ef;--muted:#aaa9a1;--line:#393a35;--green:#c7e6a1;--green-ink:#c7e6a1;--green-soft:#313131;--amber:#e4cc97;--amber-soft:#272727;--amber-line:#393a35;--shadow:0 16px 48px #00000026;--radius:16px;--motion:cubic-bezier(.22,1,.36,1)}
*{box-sizing:border-box}html{scroll-padding-top:96px}body{font-family:Manrope,"Microsoft YaHei",sans-serif;background:var(--bg);color:var(--ink);line-height:1.5}
.heading-1{font-size:60px;line-height:1;font-weight:600;letter-spacing:-.04em}.heading-3{font-size:36px;line-height:40px;font-weight:600;letter-spacing:-.025em}.title-3{font-size:16px;line-height:24px;font-weight:500}.body-3{font-size:16px;line-height:24px;font-weight:400}.caption-4{font-size:12px;line-height:16px;font-weight:500}.button-md{font-size:16px;line-height:24px;font-weight:600}
h1,h2,h3{font-family:inherit;font-weight:600}p{max-width:65ch}.wrap{max-width:1280px;padding:24px 40px 64px}.shellhead{position:sticky;top:16px;height:64px;padding:8px 12px;gap:12px;background:#1f1f1fed;backdrop-filter:blur(24px);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);margin:0 0 48px;z-index:30}.headtitle{display:flex;flex-wrap:nowrap;gap:12px;overflow:visible;min-width:0}.headtitle h1{white-space:nowrap;font-size:20px;line-height:28px;letter-spacing:-.025em;flex-shrink:0}#curtab{font-size:12px;line-height:16px;font-weight:500;white-space:nowrap;color:var(--muted)}.jiabtn{width:48px;height:48px;flex-shrink:0;border-radius:12px;font-size:24px;font-weight:600;background:var(--green);color:#181818;box-shadow:none}.badge-live{padding:8px 12px;border:0;border-radius:8px;background:transparent;color:var(--muted);font-size:12px;line-height:16px;font-weight:500;white-space:nowrap;box-shadow:none}.dot{width:8px;height:8px;box-shadow:none;background:var(--green)}
.studio-hero{display:grid;grid-template-columns:1.2fr .8fr;gap:48px;align-items:center;padding:24px 0 64px}.studio-kicker{display:flex;gap:8px;align-items:center;color:var(--green);letter-spacing:.08em;margin:0 0 24px}.studio-kicker:before{content:'';width:24px;height:2px;background:var(--green)}.studio-hero h2{max-width:680px;margin:0 0 24px;background:linear-gradient(90deg,#fff,#9b9b9b);background-clip:text;-webkit-background-clip:text;color:transparent;text-wrap:balance}.studio-copy{color:var(--muted);margin:0 0 32px;max-width:480px}.studio-cta{display:inline-flex;align-items:center;justify-content:space-between;gap:32px;background:var(--green);color:#181818;border:0;border-radius:12px;padding:12px 16px;cursor:pointer}.studio-cta span{font-size:24px;line-height:24px}.studio-proof{display:flex;gap:24px;align-items:center;margin-top:24px;color:var(--muted)}.studio-proof b{color:var(--ink);font-weight:600}.studio-art{position:relative;min-height:320px;border:1px solid var(--line);border-radius:24px;background:#1f1f1f;padding:32px;display:flex;align-items:center;justify-content:center;overflow:hidden}.studio-art:before,.studio-art:after{content:'';position:absolute;width:240px;height:240px;border:1px solid var(--line);border-radius:50%;pointer-events:none}.studio-art:after{width:320px;height:320px}.studio-stack{position:relative;width:200px;height:232px;background:#313131;border:1px solid #53554b;border-radius:16px;padding:12px;transform:rotate(-8deg);box-shadow:16px 16px 0 #272727,32px 32px 0 #222;z-index:1}.studio-stack img{width:100%;height:160px;object-fit:cover;border-radius:8px;filter:saturate(.7)}.studio-stack .studio-stack-label{display:flex;justify-content:space-between;align-items:center;padding:12px 0 0;color:var(--ink)}.studio-stamp{position:absolute;right:16px;bottom:24px;z-index:2;background:var(--green);color:#181818;border-radius:12px;padding:12px 16px;transform:rotate(6deg);box-shadow:var(--shadow)}.studio-stamp b{font-size:30px;line-height:36px;font-weight:600;display:block}.studio-art-caption{position:absolute;left:24px;top:16px;color:var(--muted);letter-spacing:.08em}
.pub-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:nowrap;margin:0 0 32px;padding:8px;background:#1f1f1f;border:1px solid var(--line);border-radius:16px}.pub-toolbar .search{margin:0;border:0;background:transparent;flex:1;min-width:0;max-width:none;font-size:16px;line-height:24px;padding:12px 16px;border-radius:8px;color:var(--ink)}.pub-toolbar .btn{flex-shrink:0}.pub-toolbar #openDrawerBtn{display:none}.btn,.tab,.qbtn,.drawer-navbtn{font-size:14px;line-height:20px;font-weight:600}.btn,.qbtn{background:#272727;border:1px solid var(--line);border-radius:8px;padding:8px 12px;color:var(--ink)}.btn.primary{background:var(--green);border-color:var(--green);color:#181818}.btn:hover,.qbtn:hover{background:#313131;color:var(--ink);border-color:#686b60}.btn.primary:hover,.studio-cta:hover{background:#d7efba;color:#181818}.btn:active,.studio-cta:active{transform:scale(.98)}
#tab-published .section{background:transparent;border:0;padding:0}.section-head{margin-bottom:24px;align-items:center}.section-head h2{font-size:30px!important;line-height:36px;letter-spacing:-.025em}.count{border:1px solid var(--line);border-radius:8px;background:#272727;font-size:12px;line-height:16px;font-weight:500;padding:8px 12px}.section .note{font-size:12px;line-height:16px;background:#272727;color:#bcbcb1;border:1px solid var(--line);border-radius:8px;padding:12px 16px;margin:16px 0}.folderbar{display:flex;gap:12px;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:thin;padding:0 0 16px;margin:24px 0 16px}.folderbar .tab{flex-shrink:0;min-width:160px;text-align:left;padding:16px;border-radius:12px;border:1px solid var(--line);background:#1f1f1f;color:var(--muted)}.folderbar .tab:before{content:'↳';display:block;font-size:24px;line-height:32px;color:var(--green);margin-bottom:16px}.folderbar .tab.active{background:#313131;border-color:#717d5e;color:var(--ink)}.folderbar #newFolderBtn{min-width:auto;color:var(--muted);border-style:dashed;background:transparent}.folderbar #newFolderBtn:before{content:'+'}#cattabs{display:flex;gap:8px;flex-wrap:nowrap;overflow-x:auto;padding:8px 0 16px;margin-bottom:16px;border:0}#cattabs .tab{flex-shrink:0;background:transparent;color:var(--muted);border:0;border-radius:8px;padding:8px 12px}#cattabs .tab.active{background:var(--green);color:#181818}
.album-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:24px;margin-top:0}.tile{aspect-ratio:auto;border-radius:16px;border:1px solid var(--line);background:#1f1f1f;overflow:hidden;align-self:start}.tileimg{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover}.tilefic{height:auto;aspect-ratio:4/3;font-size:48px;line-height:1;font-weight:500;background:#272727!important;color:var(--green)!important}.tileinfo{position:static;padding:16px 16px 48px;background:transparent;color:var(--ink)}.tile-name{display:-webkit-box!important;-webkit-line-clamp:1;line-clamp:1;font-size:14px;line-height:20px;font-weight:500;margin-bottom:8px;word-break:break-all}.tile-meta{font-size:12px;line-height:16px;color:var(--muted);opacity:1;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:32px}.tile-dl{bottom:16px;right:16px;background:#272727;border:1px solid var(--line);font-size:12px;line-height:16px;font-weight:500;padding:4px 8px;border-radius:8px;color:var(--muted)}.tile-check{top:12px;right:12px;width:24px;height:24px;border-color:#f5f5ef}.tile.selected{border-color:var(--green)}.tile.selected .tile-check{background:var(--green);color:#181818}.tile:hover{transform:translateY(-4px);border-color:#777f6c;box-shadow:var(--shadow)}
.drawer{top:0;bottom:0;left:0;width:320px;max-width:88vw;z-index:35;padding:96px 24px 24px;background:#1f1f1ff2;backdrop-filter:blur(24px);border:1px solid var(--line);transition:transform .5s var(--motion)}.drawer-backdrop{top:0;z-index:31;background:#0009;backdrop-filter:blur(4px)}.drawer-label{font-size:12px;line-height:16px;font-weight:500;letter-spacing:.08em;padding:16px 12px;color:var(--muted)}.drawer-navbtn{padding:12px 16px;margin-bottom:8px;color:var(--muted);font-weight:500;border-radius:8px;transform:translateY(24px);opacity:0;transition:transform .5s var(--motion),opacity .3s var(--motion),background-color .3s var(--motion)}.drawer.open .drawer-navbtn{transform:translateY(0);opacity:1}.drawer.open .drawer-navbtn:nth-child(2){transition-delay:60ms}.drawer.open .drawer-navbtn:nth-child(3){transition-delay:120ms}.drawer.open .drawer-navbtn:nth-child(4){transition-delay:180ms}.drawer.open .drawer-navbtn:nth-child(5){transition-delay:240ms}.drawer.open .drawer-navbtn:nth-child(6){transition-delay:300ms}.drawer-navbtn.active{background:var(--green);color:#181818;box-shadow:none}.drawer-navbtn:hover:not(.active){background:#313131;color:var(--ink);transform:translateX(4px)}.drawer:before{content:'交换站 / 导航';position:absolute;left:32px;top:32px;font-size:20px;line-height:28px;color:var(--ink)}.drawer-quota{font-size:12px;color:var(--muted)}
.studio-tagline{padding:80px 0;max-width:680px}.studio-word{display:inline-block;color:#ffffff55;transition:color .6s var(--motion)}.studio-word.visible{color:var(--ink)}.studio-footer{display:flex;justify-content:space-between;gap:24px;padding:32px 0;color:var(--muted);font-size:12px;line-height:16px}.studio-footer a{color:var(--muted)}.card{background:#1f1f1f;box-shadow:none;border-color:var(--line)}.textin,.search,.renametext{color:var(--ink);background:#272727;border-color:var(--line);font-size:16px;line-height:24px}.drop{background:#272727;border-color:#5a6052;border-radius:12px}.drop:hover{background:#313131}.note,.empty,.locked{background:#272727;color:var(--muted);border-color:var(--line)}.step,.ann-card,#previewCard{background:#1f1f1f;color:var(--ink)}.step.mid{background:#272727}.num{background:var(--green);color:#181818}.step.mid .num{background:var(--green);color:#181818}
.skip-link{position:fixed;top:-80px;left:24px;z-index:60;padding:12px 16px;background:var(--green);color:#181818}.skip-link:focus{top:8px}:where(button,a,input,select,textarea,[tabindex]):focus-visible{outline:2px solid var(--green);outline-offset:4px}.studio-cta,.tile,.jiabtn{transition:transform .5s var(--motion),background-color .3s var(--motion),border-color .3s var(--motion)}
@media(max-width:959px){.album-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.studio-hero{gap:32px}.studio-art{min-height:280px;padding:24px}.heading-1{font-size:48px;line-height:1}.studio-stack{width:160px;height:200px}.studio-stack img{height:128px}}
@media(max-width:640px){.wrap{padding:16px 16px 48px}.shellhead{top:12px;height:64px;padding:8px;gap:8px;margin-bottom:32px}.headtitle{gap:4px;flex-direction:column;align-items:flex-start}.headtitle h1{font-size:18px;line-height:28px}.badge-live{padding:4px;margin-left:auto;font-size:12px;max-width:112px;white-space:normal}.jiabtn{width:48px;height:48px}.studio-hero{display:block;padding:16px 8px 40px}.heading-1{font-size:36px;line-height:40px;letter-spacing:-.025em}.studio-kicker{margin-bottom:16px;font-size:12px}.studio-hero h2{margin-bottom:16px}.studio-copy{font-size:14px;line-height:20px;margin-bottom:24px}.studio-art{display:none}.studio-proof{gap:16px;font-size:12px;line-height:16px;margin-top:16px}.studio-cta{width:100%;padding:12px 16px}.pub-toolbar{margin-bottom:32px}.pub-toolbar .search{font-size:14px;padding:8px;line-height:20px}.pub-toolbar .btn{font-size:12px;padding:8px 12px}.section-head h2{font-size:24px!important;line-height:32px}.section-head{margin-bottom:16px}.folderbar{gap:8px;margin-top:16px}.folderbar .tab{min-width:136px;padding:12px}.folderbar .tab:before{margin-bottom:8px}.album-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.tileinfo{padding:12px 12px 40px}.tile-name{font-size:12px;line-height:16px}.tile-meta{font-size:12px;line-height:16px}.tile-dl{bottom:12px;right:12px}.studio-tagline{padding:48px 8px}.heading-3{font-size:30px;line-height:36px}.studio-footer{padding:24px 8px}.drawer{padding-top:96px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important;animation:none!important}.studio-word{color:var(--ink)}.drawer-navbtn{transform:none;opacity:1}}
"""

HERO = """<section class="studio-hero" aria-label="交换站介绍"><div><p class="studio-kicker caption-4">交换站 · 熟人的共享收藏馆</p><h2 class="heading-1"><span class="studio-title-line"><span>喜欢的东西，</span></span><span class="studio-title-line"><span>在这里相遇。</span></span></h2><p class="studio-copy body-3">图片、影音，还有值得留住的文件。<br>把你的收藏分享给朋友，也发现他们的喜欢。</p><button class="studio-cta button-md" type="button" onclick="location.hash='publish';showTab('publish')">分享一个文件 <span aria-hidden="true">↗</span></button><div class="studio-proof caption-4"><span><b>{{ files|length }}</b> 份已发布收藏</span><span>先审核，再公开</span></div></div><div class="studio-art" aria-hidden="true"><span class="studio-art-caption caption-4">FRIENDS' COLLECTION</span><div class="studio-stack">{% if files %}<img src="/thumb/{{ files[0].id }}" alt="">{% else %}<div class="tilefic">交</div>{% endif %}<div class="studio-stack-label caption-4"><span>一份喜欢，传给同好</span><span>↗</span></div></div><div class="studio-stamp caption-4"><b>{{ files|length }}</b>份共同收藏</div></div></section>"""

TAGLINE = """<section class="studio-tagline heading-3" aria-label="分享的意义"><span class="studio-word">你的收藏，</span><br><span class="studio-word">也许正是朋友在找的。</span></section><footer class="studio-footer"><span>交换站<br>留住喜欢，分享给同好。</span><a href="#principle" onclick="showTab('principle')">上传与审核规则 ↗</a></footer>"""

SCRIPT = """<script>(function(){document.querySelectorAll('.studio-word').forEach(function(w){if(matchMedia('(prefers-reduced-motion: reduce)').matches){w.classList.add('visible');return;}new IntersectionObserver(function(es,o){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');o.unobserve(e.target);}});},{threshold:1}).observe(w);});var b=document.getElementById('drawerBtn');var d=document.getElementById('drawer');if(b&&d){b.setAttribute('aria-label','打开导航');b.setAttribute('aria-controls','drawer');new MutationObserver(function(){var open=d.classList.contains('open');b.setAttribute('aria-expanded',String(open));}).observe(d,{attributes:true,attributeFilter:['class']});}document.querySelectorAll('.tileimg').forEach(function(im){var t=im.closest('.tile');if(t)im.alt=t.dataset.name||'文件预览';});})();</script>"""

def build_studio_page(page):
    page = page.replace('</head>', '<meta name="description" content="交换站，熟人之间的共享收藏馆。上传文件，经审核后分享给朋友。"><style id="studio-design">' + STUDIO_CSS + '</style></head>', 1)
    page = page.replace('<body>', '<body><a class="skip-link" href="#albumGrid">跳到文件列表</a>', 1)
    page = page.replace('<div class="tabpanel active" id="tab-published">', '<div class="tabpanel active" id="tab-published">' + HERO, 1)
    page = page.replace('<h2>已发布</h2>', '<h2>大家的收藏</h2>', 1)
    page = page.replace('<div id="previewOverlay">', TAGLINE + '<div id="previewOverlay">', 1)
    page = page.replace('<div class="drawer-label">外观</div>', '<div class="drawer-label">动效</div><button id="motionBtn" class="drawer-navbtn" type="button">动效：开启 · 点击关闭</button><div class="drawer-label">外观</div>', 1)
    motion = '<style>.shellhead{z-index:40}.studio-title-line{display:block;overflow:hidden}.studio-title-line span{display:block}.gsap-motion .drawer,.gsap-motion .drawer-backdrop,.gsap-motion .drawer-navbtn{transition:none}.gsap-motion .drawer{transform:none}.gsap-motion #drawernav .drawer-navbtn{opacity:1}.gsap-motion .tile{will-change:transform,opacity}.folderbar{scrollbar-width:none}.folderbar::-webkit-scrollbar{display:none}.folderbar #newFolderBtn:before{content:""}.studio-hero h2{overflow:hidden}</style><script src="/static/gsap.min.js" defer></script><script src="/static/CustomEase.min.js" defer></script><script src="/static/studio-motion.js" defer></script>'
    return page.replace('</body>', SCRIPT + motion + '</body>', 1)
